head.script:
//
(function(){
  const XHTML_NS = "http://www.w3.org/1999/xhtml";
  const root = document.querySelector("foreignObject").firstElementChild;
  const originalCreateElement = document.createElement.bind(document);
  const originalCreateElementNS = document.createElementNS.bind(document);
  Object.defineProperty(document, "head", { get(){ return root.querySelector("head"); }, configurable: true });
  Object.defineProperty(document, "body", { get(){ return root.querySelector("body"); }, configurable: true });
  Object.defineProperty(document, "documentElement", { get(){ return root; }, configurable: true });
  document.createElement = function(tagName, options) {
    if (typeof tagName === "string") return originalCreateElementNS(XHTML_NS, tagName, options);
    return originalCreateElement(tagName, options);
  };
  document.createElementNS = function(namespaceURI, qualifiedName, options) {
    if (namespaceURI == null || namespaceURI === XHTML_NS) return originalCreateElementNS(XHTML_NS, qualifiedName, options);
    return originalCreateElementNS(namespaceURI, qualifiedName, options);
  };
})();
//

body.script:
//
(function() {
  var currentUrl = '';
  var historyStack = [];
  var historyIndex = -1;

  var webview = document.getElementById('webview');
  var homeScreen = document.getElementById('home-screen');
  var loader = document.getElementById('loader');
  var loaderMsg = document.getElementById('loader-msg');
  var loaderUrl = document.getElementById('loader-url');
  var urlInput = document.getElementById('url-input');
  var heroInput = document.getElementById('hero-input');
  var engineSelect = document.getElementById('proxy-engine');
  var toastEl = document.getElementById('toast');

  var btnBack = document.getElementById('btn-back');
  var btnFwd = document.getElementById('btn-fwd');
  var btnReload = document.getElementById('btn-reload');
  var btnGo = document.getElementById('btn-go');
  var btnHome = document.getElementById('btn-home');
  var btnCloak = document.getElementById('btn-cloak');
  var btnPanic = document.getElementById('btn-panic');
  var disguiseSelect = document.getElementById('disguise-select');

  function showToast(msg) {
    toastEl.textContent = msg;
    toastEl.classList.add('show');
    setTimeout(function() { toastEl.classList.remove('show'); }, 3000);
  }

  function updateNavButtons() {
    btnBack.disabled = (historyIndex <= 0);
    btnFwd.disabled = (historyIndex >= historyStack.length - 1);
  }

  function normalizeUrl(input) {
    input = input.trim();
    if (!input) return '';
    if (/^https?:\/\//i.test(input)) return input;
    if (input.indexOf('.') !== -1 && input.indexOf(' ') === -1) {
      return 'https://' + input;
    }
    return 'https://www.google.com/search?q=' + encodeURIComponent(input);
  }

  function showLoader(msg, url) {
    loaderMsg.textContent = msg || 'Connecting through proxy…';
    loaderUrl.textContent = url || '';
    loader.classList.add('active');
  }

  function hideLoader() {
    loader.classList.remove('active');
  }

  var PROXY_GATEWAYS = [
    function(u) { return 'https://api.allorigins.win/raw?url=' + encodeURIComponent(u); },
    function(u) { return 'https://corsproxy.io/?' + encodeURIComponent(u); },
    function(u) { return 'https://api.codetabs.com/v1/proxy?quest=' + encodeURIComponent(u); },
    function(u) { return 'https://thingproxy.freeboard.io/fetch/' + encodeURIComponent(u); }
  ];

  function navigate(rawUrl, skipHistory) {
    var target = normalizeUrl(rawUrl);
    if (!target) return;

    currentUrl = target;
    urlInput.value = target;

    if (!skipHistory) {
      historyStack = historyStack.slice(0, historyIndex + 1);
      historyStack.push(target);
      historyIndex = historyStack.length - 1;
      updateNavButtons();
    }

    homeScreen.classList.add('hide');
    webview.classList.add('active');

    var engine = engineSelect.value;

    if (engine === 'direct') {
      showLoader('Connecting directly…', target);
      webview.onload = function() { hideLoader(); showToast('Loaded direct embed'); };
      webview.onerror = function() { hideLoader(); showToast('Direct embed blocked - switch engine'); };
      webview.src = target;
      return;
    }

    showLoader('Connecting through CDN Multi-Proxy…', target);
    fetchProxiedHtml(target, 0);
  }

  function fetchProxiedHtml(url, gatewayIndex) {
    if (gatewayIndex >= PROXY_GATEWAYS.length) {
      showLoader('Attempting direct fallback…', url);
      webview.onload = function() { hideLoader(); showToast('Loaded direct fallback'); };
      webview.onerror = function() { hideLoader(); showToast('Failed to load website'); };
      webview.src = url;
      return;
    }

    var proxyUrl = PROXY_GATEWAYS[gatewayIndex](url);
    var timeoutSignal = window.AbortSignal && window.AbortSignal.timeout ? window.AbortSignal.timeout(7000) : null;

    fetch(proxyUrl, { signal: timeoutSignal })
      .then(function(res) {
        if (!res.ok) throw new Error('HTTP ' + res.status);
        return res.text();
      })
      .then(function(html) {
        hideLoader();

        var origin = (url.match(/^(https?:\/\/[^\/]+)/i) || ['', url])[1];
        var baseHref = url.replace(/([^/])\/?$/, '$1/');
        var baseTag = '<base href="' + baseHref + '">';

        if (/<head(\s[^>]*)?>/i.test(html)) {
          html = html.replace(/<head(\s[^>]*)?>/i, '$&\n' + baseTag);
        } else {
          html = baseTag + '\n' + html;
        }

        var interceptScript = '<script>'
          + 'document.addEventListener("click", function(e) {'
          + '  var a = e.target.closest("a");'
          + '  if (a && a.href) {'
          + '    e.preventDefault();'
          + '    window.parent.postMessage({ type: "NXP_NAV", url: a.href }, "*");'
          + '  }'
          + '}, true);'
          + 'document.addEventListener("submit", function(e) {'
          + '  var f = e.target;'
          + '  if (f && f.action) {'
          + '    e.preventDefault();'
          + '    var data = new FormData(f);'
          + '    var params = new URLSearchParams(data).toString();'
          + '    var full = f.action + (f.action.indexOf("?") === -1 ? "?" : "&") + params;'
          + '    window.parent.postMessage({ type: "NXP_NAV", url: full }, "*");'
          + '  }'
          + '}, true);'
          + '<\/script>';

        html = html.replace(/<\/body>/i, interceptScript + '</body>');

        webview.removeAttribute('src');
        webview.srcdoc = html;
        showToast('⚡ Loaded via Gateway #' + (gatewayIndex + 1));
      })
      .catch(function(err) {
        fetchProxiedHtml(url, gatewayIndex + 1);
      });
  }

  window.addEventListener('message', function(e) {
    if (e.data && e.data.type === 'NXP_NAV' && e.data.url) {
      navigate(e.data.url);
    }
  });

  btnGo.addEventListener('click', function() { navigate(urlInput.value); });
  urlInput.addEventListener('keydown', function(e) { if (e.key === 'Enter') navigate(this.value); });
  var heroGo = document.getElementById('hero-go');
  heroGo.addEventListener('click', function() { navigate(heroInput.value); });
  heroInput.addEventListener('keydown', function(e) { if (e.key === 'Enter') navigate(this.value); });

  btnHome.addEventListener('click', function() {
    homeScreen.classList.remove('hide');
    webview.classList.remove('active');
    hideLoader();
    urlInput.value = '';
  });

  btnBack.addEventListener('click', function() {
    if (historyIndex > 0) {
      historyIndex--;
      navigate(historyStack[historyIndex], true);
      updateNavButtons();
    }
  });

  btnFwd.addEventListener('click', function() {
    if (historyIndex < historyStack.length - 1) {
      historyIndex++;
      navigate(historyStack[historyIndex], true);
      updateNavButtons();
    }
  });

  btnReload.addEventListener('click', function() {
    if (currentUrl) navigate(currentUrl, true);
  });

  document.querySelectorAll('.card').forEach(function(card) {
    card.addEventListener('click', function() {
      var url = this.getAttribute('data-url');
      if (url) navigate(url);
    });
  });

  function panic() {
    window.location.replace('https://classroom.google.com');
  }
  btnPanic.addEventListener('click', panic);
  window.addEventListener('keydown', function(e) {
    if (e.key === '`' || e.key === '~') panic();
  });

  btnCloak.addEventListener('click', function() {
    var win = window.open('about:blank', '_blank');
    if (!win) {
      showToast('Pop-up blocked! Allow popups to use cloaking.');
      return;
    }
    var doc = win.document;
    doc.title = document.title;
    var fav = doc.createElement('link');
    fav.rel = 'icon';
    fav.href = document.getElementById('tab-favicon').href;
    doc.head.appendChild(fav);

    var iframe = doc.createElement('iframe');
    iframe.style.position = 'fixed';
    iframe.style.inset = '0';
    iframe.style.width = '100vw';
    iframe.style.height = '100vh';
    iframe.style.border = 'none';
    iframe.setAttribute('allow', 'fullscreen; autoplay; clipboard-write; encrypted-media; camera; microphone');
    iframe.src = window.location.href;

    doc.body.style.margin = '0';
    doc.body.style.overflow = 'hidden';
    doc.body.appendChild(iframe);

    win.addEventListener('keydown', function(e) {
      if (e.key === '`' || e.key === '~') {
        win.location.replace('https://classroom.google.com');
      }
    });

    showToast('🕶️ Opened in about:blank cloaked tab!');
  });

  var DISGUISES = {
    classroom: { title: 'Classes', icon: 'https://ssl.gstatic.com/classroom/favicon.png' },
    drive: { title: 'My Drive - Google Drive', icon: 'https://ssl.gstatic.com/docs/doclist/images/drive_2022q3_32dp.png' },
    docs: { title: 'Google Docs', icon: 'https://ssl.gstatic.com/docs/documents/images/kix-favicon7.ico' },
    canvas: { title: 'Dashboard', icon: 'https://du11hjcvx0uqb.cloudfront.net/dist/images/favicon-e10d657a73.ico' },
    khan: { title: 'Dashboard | Khan Academy', icon: 'https://www.khanacademy.org/favicon.ico' }
  };

  disguiseSelect.addEventListener('change', function() {
    var d = DISGUISES[this.value];
    if (d) {
      document.title = d.title;
      document.getElementById('tab-favicon').href = d.icon;
      showToast('🎭 Disguised as ' + d.title);
    }
  });

})();
//
